package controller;
import dao.*; import model.Vendor; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.*;
public class VendorSignupServlet extends HttpServlet {protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{VendorDAO vd=new VendorDAO();String email=r.getParameter("email");if(vd.emailExists(email)){r.setAttribute("error","Vendor email already exists.");r.getRequestDispatcher("/vendorSignup.jsp").forward(r,s);return;}String acc=r.getParameter("accountNumber"),holder=r.getParameter("accountHolder"),bank=r.getParameter("bankName"),pin=r.getParameter("pin");if(acc==null||holder==null||bank==null||pin==null){r.setAttribute("error","Complete bank details.");r.getRequestDispatcher("/vendorSignup.jsp").forward(r,s);return;}BankAccountDAO bd=new BankAccountDAO();if(bd.getByAccountNumber(acc)!=null){r.setAttribute("error","Bank account number already exists.");r.getRequestDispatcher("/vendorSignup.jsp").forward(r,s);return;}String sql="INSERT INTO bank_accounts(account_number,account_holder,bank_name,balance,pin,account_type) VALUES(?,?,?,0,?,'VENDOR')";int bankId;try(java.sql.Connection c=DBConnection.getConnection();java.sql.PreparedStatement p=c.prepareStatement(sql,java.sql.Statement.RETURN_GENERATED_KEYS)){p.setString(1,acc);p.setString(2,holder);p.setString(3,bank);p.setString(4,pin);p.executeUpdate();try(java.sql.ResultSet k=p.getGeneratedKeys()){if(!k.next())throw new Exception("Bank account creation failed");bankId=k.getInt(1);}}Vendor v=new Vendor();v.setVendorName(r.getParameter("vendorName"));v.setEmail(email);v.setPassword(r.getParameter("password"));v.setContact(r.getParameter("contact"));v.setAddress(r.getParameter("address"));v.setDescription(r.getParameter("description"));v.setSecurityQuestion(r.getParameter("securityQuestion"));v.setSecurityAnswer(r.getParameter("securityAnswer"));vd.registerVendor(v,bankId);s.sendRedirect(r.getContextPath()+"/vendorLogin.jsp?registered=1");}catch(Exception e){throw new ServletException(e);}}}